@container ohmylms-mindmap (max-width: 1000px) {

	.ohmylms-mindmap-stage {
		display: block;
		width: 100%;
		min-width: 0;
	}

	.ohmylms-mindmap-node {
		width: 100%;
		min-width: 0;
	}

	.ohmylms-mindmap-root {
		width: 100%;
		min-width: 0;
		margin-bottom: 16px;
	}

	.ohmylms-mindmap-branches {
		padding-left: 16px;
		min-width: 0;
	}

	.ohmylms-mindmap-root::after {
		display: none;
	}

	.ohmylms-mindmap-branches > li {
		flex-direction: column;
		align-items: stretch;
		gap: 0;
		min-width: 0;
	}

	.ohmylms-mindmap-branches > li::before {
		top: 24px;
		left: -16px;
		width: 16px;
	}

	.ohmylms-mindmap-node.has-children::after {
		display: none;
	}
}

